package com.maxstream.app.update

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull

class ChecksumTest {
    private val sums = """
        # generated by sha256sum
        2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824  maxstream-arm64-v8a.apk
        a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447 *MaxStream-Dex.exe

        ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789  MaxStream-Desktop.msi
    """.trimIndent()

    @Test
    fun parsesSha256sumOutput() {
        assertEquals(
            "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824",
            Checksum.findForFile(sums, "maxstream-arm64-v8a.apk"),
        )
        assertEquals(
            "a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447",
            Checksum.findForFile(sums, "MaxStream-Dex.exe"),
        )
        assertEquals(
            "abcdef0123456789abcdef0123456789abcdef0123456789abcdef0123456789",
            Checksum.findForFile(sums, "MaxStream-Desktop.msi"),
        )
    }

    @Test
    fun acceptsPathPrefixedEntries() {
        assertEquals(
            "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824",
            Checksum.findForFile(
                "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824  release-assets/MaxStream-Dex.exe",
                "MaxStream-Dex.exe",
            ),
        )
    }

    @Test
    fun returnsNullForMissingOrMalformedEntries() {
        assertNull(Checksum.findForFile(sums, "MaxStream-Other.exe"))
        assertNull(Checksum.findForFile("", "MaxStream-Dex.exe"))
        assertNull(Checksum.findForFile("not a checksum line", "MaxStream-Dex.exe"))
    }

    @Test
    fun extractsAssetNameFromDownloadUrl() {
        assertEquals(
            "MaxStream-Dex.exe",
            Checksum.assetNameFromUrl(
                "https://github.com/TeamMaxStream/MaxStream/releases/download/v1.8.0/MaxStream-Dex.exe",
            ),
        )
        assertEquals(
            "maxstream-arm64-v8a.apk",
            Checksum.assetNameFromUrl(
                "https://github.com/TeamMaxStream/MaxStream/releases/download/v1.8.0/" +
                    "maxstream-arm64-v8a.apk?download=1",
            ),
        )
    }

    @Test
    fun hashesFileContents() {
        val file = kotlin.io.path.createTempFile("maxstream-checksum", ".bin").toFile()
        try {
            file.writeText("hello")
            assertEquals(
                "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824",
                Checksum.sha256Of(file),
            )
        } finally {
            file.delete()
        }
    }

    @Test
    fun hashesFilesLargerThanTheReadBuffer() {
        val file = kotlin.io.path.createTempFile("maxstream-checksum-large", ".bin").toFile()
        try {
            val bytes = ByteArray(1024 * 1024 + 17) { (it % 251).toByte() }
            file.writeBytes(bytes)
            val expected = java.security.MessageDigest
                .getInstance("SHA-256")
                .digest(bytes)
                .joinToString("") { "%02x".format(it) }
            assertEquals(expected, Checksum.sha256Of(file))
        } finally {
            file.delete()
        }
    }
}
